package com.example.todo.security; import com.example.todo.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService { private final UserRepository repo; public UserDetails loadUserByUsername(String u){var x=repo.findByUsername(u).orElseThrow(()->new UsernameNotFoundException("User not found"));return User.withUsername(x.getUsername()).password(x.getPassword()).roles("USER").build();} }
